// MQTT CSV contract unchanged: lat,lng,speed,sat,throttle,current_mA,V,W,Wh,km,millis.
// Distance: trapezoidal speed integration, km/h * seconds / 3600.
// Optional raw odometer (km) only recovers gaps >3 seconds when plausible.
// Target 250 s + existing carry-over. Ticks NEVER integrate distance.
// First sample establishes baseline; pre-baseline/missing intervals are not fabricated.
const CFG = { targetTime: 220, targetEnergy: 7, maxSpeed: 80, maxPower: 5000, maxBridge: 3 };
const now = Date.now();
let st = context.get('paddockV2');
function fresh() { return { running: false, started: 0, lapStart: 0, stopped: 0, lap: 0, d: 0, e: 0, ld: 0, le: 0, carry: 0, prev: null, last: null, tele: null, quality: 'Menunggu telemetri', seen: [], distanceVersion: 3, distanceGapSeconds: 0 }; }
if (!st) st = fresh();
// Upgrade without inventing distance for intervals already lost by the old parser.
if (st.distanceVersion !== 3) { st.distanceVersion = 3; st.prev = null; st.seen = []; st.distanceGapSeconds = 0; }

const fmt = s => { const n = Math.round(Math.abs(s) * 1000); return (s < 0 ? '-' : '') + String(Math.floor(n / 60000)).padStart(2, '0') + ':' + String(Math.floor(n / 1000) % 60).padStart(2, '0') + '.' + String(n % 1000).padStart(3, '0'); };
const eff = (d, e) => e >= 0.01 && d > 0 ? d * 1000 / e : null;
let ctl = null, log = null, map = null;
let cmd = typeof msg.payload === 'string' ? msg.payload.trim() : '';
function finishLap() { const t = (now - st.lapStart) / 1000; st.last = { time: fmt(t), energy: st.le.toFixed(3), distance: st.ld.toFixed(3), eff: eff(st.ld, st.le), avg: t > 0 ? st.ld * 3600 / t : 0 }; return t; }
if (cmd === 'START_SESSION') {
    if (!st.running) { st = fresh(); st.running = true; st.started = st.lapStart = now; st.lap = 1; ctl = { payload: { cmd: 'START', timestamp: now } }; }
} else if (cmd === 'RECORD_LAP') {
    if (st.running && now - st.lapStart >= 1000) { const t = finishLap(); st.carry = Math.max(1 - CFG.targetTime, st.carry + CFG.targetTime - t); st.ld = 0; st.le = 0; st.lapStart = now; st.lap++; st.prev = null; ctl = { payload: { cmd: 'LAP', timestamp: now } }; }
} else if (cmd === 'STOP_SESSION') {
    if (st.running) { finishLap(); st.running = false; st.stopped = now; st.prev = null; ctl = { payload: { cmd: 'STOP', timestamp: now } }; }
} else if (cmd === 'RESET_ALL') {
    st = fresh(); ctl = { payload: { cmd: 'RESET', timestamp: now } };
} else if (msg.topic !== 'paddock/tick') {
    if (msg.topic === 'rakata/lap_result' || msg.payload && msg.payload.type === 'LAP_RESULT') return null;
    const str = Buffer.isBuffer(msg.payload) ? msg.payload.toString() : String(msg.payload || '');
    const p = str.trim().split(','); if (p.length < 11) return null;
    const nums = p.slice(0, 11).map(x => x.trim() === '' ? NaN : Number(x));
    // Optional raw distance can be blank: speed integration remains available.
    if (!nums.every((v, i) => i === 9 || Number.isFinite(v))) return null;
    const [lat, lng, speed, sat, throttle, ma, v, w, er, dr, ms] = nums;
    if (speed < 0 || speed > CFG.maxSpeed || er < 0 || ms < 0 || v < 0 || v > 150 || Math.abs(ma) > 200000) return null;
    const t = { lat, lng, speed, sat, throttle, ma, v, w, er, dr, ms, at: now };
    // Retained MQTT is historical, not a new measurement.
    if (msg.retain === true) return null;
    const key = nums.join(',');
    const duplicate = st.seen.includes(key);
    let outOfOrder = false;
    if (st.prev && ms < st.prev.ms) { outOfOrder = !(ms < 10000 && (er < st.prev.er || dr < st.prev.dr)); }
    if (!duplicate && !outOfOrder) {
        st.seen.push(key); if (st.seen.length > 100) st.seen.shift();
        let dd = 0, de = 0; st.quality = 'Baseline';
        if (st.running && st.prev) {
            const a = st.prev, wall = (now - a.at) / 1000, src = (ms - a.ms) / 1000;
            const dt = src > 0 && Math.abs(src - wall) < Math.max(2, wall * .25) ? src : wall;
            const bridge = dt > 0 && dt <= CFG.maxBridge;
            const rd = dr - a.dr, re = er - a.er;
            const validD = Number.isFinite(rd) && rd > 0 && rd <= CFG.maxSpeed * dt / 3600 + 0.002;
            const validE = re >= 0 && re <= CFG.maxPower * dt / 3600 + 0.02;
            // One source per interval: integrate speed (km/h) over time (seconds).
            // Do NOT also add raw odometer increments: that would double count.
            let distanceSource = 'Jarak tidak terukur';
            if (bridge) { dd = (speed + a.speed) * 0.5 * dt / 3600; distanceSource = 'Jarak: integrasi speed'; }
            else if (dt > 0 && validD) { dd = rd; distanceSource = 'Jarak: counter saat gap'; }
            else if (dt > 0) { st.distanceGapSeconds = (st.distanceGapSeconds || 0) + dt; }

            if (validE) de = re; else if (bridge) de = (Math.max(0, v * ma / 1000) + Math.max(0, a.v * a.ma / 1000)) * .5 * dt / 3600;
            st.quality = distanceSource + (validE ? ' · Wh: counter' : bridge ? ' · Wh: estimasi' : ' · Wh: gap');
            st.d += dd; st.ld += dd; st.e += de; st.le += de;
        }
        st.tele = t; st.prev = t;
    } else st.quality = duplicate ? 'Duplikat diabaikan' : 'Paket lama diabaikan';
    // Keep original 12-column CSV and file node. Valid duplicates still logged as received.
    if (st.running) log = { payload: `${new Date(now).toISOString()},${lat.toFixed(6)},${lng.toFixed(6)},${speed.toFixed(2)},${sat},${throttle},${ma.toFixed(3)},${v.toFixed(2)},${w.toFixed(2)},${er.toFixed(4)},${st.d.toFixed(3)},${ms}` };
    if (!duplicate && !outOfOrder && sat > 0 && Math.abs(lat) <= 90 && Math.abs(lng) <= 180 && lat !== 0 && lng !== 0) map = { payload: { name: 'RAKATA_EV', lat, lon: lng, heading: 0, icon: 'fa-location-arrow', iconColor: 'red', track: true, ttl: 180 } };
}
const t = st.tele || {}, end = st.running ? now : st.stopped;
const elapsed = st.lap ? Math.max(0, (end - st.lapStart) / 1000) : 0;
const total = st.lap ? Math.max(0, (end - st.started) / 1000) : 0;
const remain = CFG.targetTime + st.carry - elapsed;
const f = (x, n = 2) => Number(x || 0).toFixed(n);
const efficiency = eff(st.d, st.e);
const ui = { payload: { speed: f(t.speed, 1), speedPct: Math.min(100, (t.speed || 0) * 2), avgSpeed: total > 0 ? f(st.d * 3600 / total) : '0.00', current: f((t.ma || 0) / 1000), voltage: f(t.v, 1), power: f(t.w, 0), energy: f(st.le, 3), remEnergy: f(Math.max(0, CFG.targetEnergy - st.le), 3), throttle: t.throttle || 0, sat: t.sat || 0, currentLap: st.lap ? fmt(elapsed) : '--:--.---', countdown: st.lap ? fmt(remain) : '--:--.---', countdownColor: remain < 0 ? '#ff647c' : remain < 60 ? '#ffd36b' : '#60e6b1', lastLapTime: st.last ? st.last.time : '--:--.---', lastLapEnergy: st.last ? st.last.energy : '0.000', lastLapKmPerKwh: st.last && st.last.eff !== null ? f(st.last.eff) : '—', distance: f(st.d, 3), lapDistance: f(st.ld, 3), kmPerKwh: efficiency === null ? '—' : f(efficiency), lat: t.lat, lng: t.lng, age: t.at ? (now - t.at) / 1000 : 999, running: st.running, lap: st.lap, quality: st.quality + ((st.distanceGapSeconds || 0) > 0 ? ' · gap jarak ' + st.distanceGapSeconds.toFixed(1) + ' s' : ''), targetTime: CFG.targetTime, distanceGapSeconds: st.distanceGapSeconds || 0, status: st.running ? 'RUNNING' : st.lap ? 'STOPPED' : 'READY' } };
context.set('paddockV2', st);
return [ui, map, null, log, ctl, null];
